def commit(state, batch):
    # Never mutate caller-owned data: copy balances and seen up front.
    result = {
        'balances': dict(state['balances']),
        'seen': dict(state['seen']),
    }
    balances = result['balances']
    seen = result['seen']

    for event in batch:
        event_id, src, dst, amount = event

        # 1. Validity first: positive integer amount (booleans are invalid),
        #    transferring between existing, distinct accounts.
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            raise ValueError("invalid")
        if src == dst or src not in balances or dst not in balances:
            raise ValueError("invalid")

        # 2. ID reuse: skip an identical transfer, else conflict.
        if event_id in seen:
            if seen[event_id] == [src, dst, amount]:
                continue
            raise ValueError("conflict")

        # 3. Funds: insufficient balance raises.
        if balances[src] < amount:
            raise ValueError("funds")

        # Apply the transfer.
        balances[src] -= amount
        balances[dst] += amount
        seen[event_id] = [src, dst, amount]

    return result

