from ledger import commit


def _coerce_state(snapshot):
    """Accept a current state snapshot or a legacy bare balance mapping.

    A current snapshot maps 'balances' to a dict of accounts. A legacy bare
    mapping maps account names to integer balances, and may even include an
    account literally named "balances" (whose value is an integer, not a dict).
    """
    if isinstance(snapshot, dict) and isinstance(snapshot.get('balances'), dict):
        return {
            'balances': dict(snapshot['balances']),
            'seen': dict(snapshot.get('seen', {})),
        }
    # Legacy bare balance mapping (all integer values, possibly incl. "balances").
    return {'balances': dict(snapshot), 'seen': {}}


def restore(snapshot, batches):
    state = _coerce_state(snapshot)
    rejected = []
    for index, batch in enumerate(batches):
        try:
            state = commit(state, batch)
        except ValueError:
            # A rejected batch is atomic: discard it and continue from the
            # last accepted state (commit never mutates its input).
            rejected.append(index)
    return [state, rejected]
